// Modified distribution, 2026-09-29. SPDX-License-Identifier: AGPL-3.0-only
// No new network protocol: configuration and session policy around RustDesk OSS.
use hbb_common::{config::{self, Config}, password_security, tokio::sync::watch};
#[path = "support_brand.rs"]
pub mod brand;

lazy_static::lazy_static! {
    static ref SESSION_OPEN: watch::Sender<bool> = watch::channel(false).0;
    static ref SESSION_CONTROL: std::sync::Mutex<()> = std::sync::Mutex::new(());
}

pub fn is_customer() -> bool {
    is_custom() && brand::CUSTOMER
}

pub fn is_custom() -> bool {
    cfg!(all(any(windows, target_os = "macos"), feature = "custom-support"))
}

pub fn offline_build() -> bool { is_custom() && !brand::CONFIGURED }

pub fn outgoing_error(peer: &str, has_other_server: bool) -> Option<&'static str> {
    if !is_custom() { return None; }
    if offline_build() { return Some("Server non configurato: installare una build aziendale configurata"); }
    if is_customer() { return Some("Usare il profilo operatore per avviare una connessione"); }
    if has_other_server || peer.is_empty() || !peer.bytes().all(|b| b.is_ascii_digit()) {
        return Some("Inserire un ID numerico del server aziendale; indirizzi e server alternativi non sono consentiti");
    }
    None
}

pub fn enabled() -> bool {
    *SESSION_OPEN.borrow() && !Config::get_bool_option("stop-service")
}

pub fn configure() {
    *config::APP_NAME.write().unwrap() = brand::APP_NAME.to_owned();
    #[cfg(target_os = "macos")]
    {
        *config::ORG.write().unwrap() = brand::COMPANY_NAME.to_owned();
    }
    *config::EXE_RENDEZVOUS_SERVER.write().unwrap() = brand::ID_SERVER.to_owned();
    let mut options = config::OVERWRITE_SETTINGS.write().unwrap();
    for (key, value) in [
        ("custom-rendezvous-server", brand::ID_SERVER),
        ("relay-server", brand::RELAY_SERVER), ("key", brand::PUBLIC_KEY),
        ("api-server", ""), ("enable-check-update", "N"),
        ("allow-auto-update", "N"), ("direct-server", "N"),
        ("enable-lan-discovery", "N"),
        ("enable-ipv6-punch", "N"),
    ] { options.insert(key.to_owned(), value.to_owned()); }
    if is_customer() {
        for (key, value) in [
            ("access-mode", "custom"),
            ("verification-method", "use-temporary-password"),
            ("temporary-password-length", "10"), ("approve-mode", "both"),
            ("allow-numeric-one-time-password", "N"),
            ("enable-trusted-devices", "N"),
            ("allow-hide-cm", "N"), ("enable-privacy-mode", "N"),
            ("enable-block-input", "N"), ("enable-terminal", "N"),
            ("enable-tunnel", "N"), ("enable-camera", "N"),
            ("enable-remote-restart", "N"), ("allow-remote-config-modification", "N"),
        ] { options.insert(key.to_owned(), value.to_owned()); }
    }
    drop(options);
    let mut builtin = config::BUILTIN_SETTINGS.write().unwrap();
    for key in ["allow-logon-screen-password", "allow-deep-link-password",
        "allow-deep-link-server-settings", "hide-tray"] {
        builtin.insert(key.to_owned(), "N".to_owned());
    }
    drop(builtin);
    let mut hard = config::HARD_SETTINGS.write().unwrap();
    hard.insert("disable-account".into(), "Y".into());
    hard.insert("disable-ab".into(), "Y".into());
    hard.insert("disable-installation".into(), "Y".into());
    if is_customer() {
        hard.insert("conn-type".into(), "incoming".into());
        hard.insert("disable-settings".into(), "Y".into());
    } else {
        hard.insert("conn-type".into(), "outgoing".into());
    }
}

pub fn set_enabled(value: bool) -> String {
    if !is_customer() { return "Not a customer support profile".into(); }
    let _control = SESSION_CONTROL.lock().unwrap();
    if value && !crate::common::is_server_running() {
        return "Inizializzazione in corso: riprova tra qualche secondo. Se persiste, chiudi le altre copie del cliente e riapri questa app".into();
    }
    // Close the in-memory gate first. It is deliberately never restored from disk.
    SESSION_OPEN.send_replace(false);
    Config::set_option("stop-service".into(), "Y".into());
    password_security::update_temporary_password();
    if value && (!brand::CONFIGURED || brand::ID_SERVER.is_empty() || brand::PUBLIC_KEY.is_empty()) {
        return "Server non configurato: ricompilare con config/client.env".into();
    }
    #[cfg(target_os = "macos")]
    if value && (!crate::platform::macos::is_can_screen_recording(false)
        || !crate::platform::macos::is_process_trusted(false)) {
        return "Abilita Registrazione schermo e Accessibilità in Impostazioni di Sistema > Privacy e sicurezza, poi riapri l’app".into();
    }
    if value {
        Config::set_option("stop-service".into(), "".into());
        SESSION_OPEN.send_replace(true);
    }
    #[cfg(not(target_os = "ios"))]
    crate::rendezvous_mediator::RendezvousMediator::restart();
    String::new()
}

// IPC option snapshots can be stale, especially when the consent window opens.
// Only explicit support controls may change the customer's session gate.
pub fn set_options(mut options: std::collections::HashMap<String, String>) {
    let _control = SESSION_CONTROL.lock().unwrap();
    if *SESSION_OPEN.borrow() {
        options.remove("stop-service");
    } else {
        options.insert("stop-service".into(), "Y".into());
    }
    Config::set_options(options);
}

pub fn subscribe() -> watch::Receiver<bool> { SESSION_OPEN.subscribe() }

pub async fn wait_until_stopped(receiver: &mut watch::Receiver<bool>) {
    if !is_customer() { std::future::pending::<()>().await; return; }
    if !enabled() { return; }
    // Any transition invalidates existing sessions, even a rapid Stop then Start.
    match receiver.changed().await { Ok(()) | Err(_) => return }
}

